// Les plugins ajoutent des capacites : 'java' sait compiler et packager du Java.
plugins {
    id 'java'
}

// Les memes coordonnees qu'en Maven : group + name (via le dossier) + version.
group = 'com.exemple'
version = '1.0.0'

java {
    // On compile pour Java 21.
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

// Ou Gradle va chercher les dependances (voir la lecon suivante).
repositories {
    mavenCentral()
}

dependencies {
    // Les dependances se declarent ici, une ligne par bibliotheque.
}

// Fichier module-info.java, place a la racine des sources du module.
module com.exemple.monapp {

    // Ce module A BESOIN d'un autre module pour fonctionner.
    requires java.sql;

    // Ce module EXPOSE ce paquet : les autres modules pourront l'utiliser.
    exports com.exemple.monapp.api;

    // Le paquet com.exemple.monapp.interne n'est PAS exporte :
    // il reste prive, invisible depuis l'exterieur du module.
}

dependencies {
    // Une seule ligne par dependance, au format 'groupId:artifactId:version'.
    implementation 'com.google.code.gson:gson:2.11.0'

    // testImplementation = dependance utilisee seulement par les tests.
    testImplementation 'org.junit.jupiter:junit-jupiter:5.11.0'
}

// Remarque : les memes coordonnees GAV qu'en Maven, ecrites en plus court.
// 'implementation' et 'testImplementation' precisent QUAND la dependance sert.
